INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7515522, 1200305, 114285, '<td valign="top">I dislike slugs, but I really like the colours in this.</td>', 'I dislike slugs, but I really like the colours in this.', '2017-05-26 01:16:31.000000', NULL, 1),
(7515528, 1200169, 83845, '<td valign="top">LOL</td>', 'LOL', '2017-05-26 02:08:42.000000', NULL, 1),
(7515541, 1200402, 67258, '<td valign="top">Such a shame the wing tip has been cut-off - the composition all needed shifting a smidge to the left. A slightly deeper dof would have been benficial, but difficult to achieve with macros, and you may have needed the extra shutter speed. Nonetheless, a good entry with some lovely detail on the hairs of the bee.</td>', 'Such a shame the wing tip has been cut-off - the composition all needed shifting a smidge to the left. A slightly deeper dof would have been benficial, but difficult to achieve with macros, and you may have needed the extra shutter speed. Nonetheless, a good entry with some lovely detail on the hairs of the bee.', '2017-05-26 07:31:13.000000', NULL, 1),
(7515542, 1200222, 67258, '<td valign="top">What a great find!</td>', 'What a great find!', '2017-05-26 07:31:46.000000', NULL, 1),
(7515543, 1200069, 67258, '<td valign="top">The shadow adjustment is a little bit too much for my taste, but an interesting capture.</td>', 'The shadow adjustment is a little bit too much for my taste, but an interesting capture.', '2017-05-26 07:32:31.000000', NULL, 1),
(7515544, 1200386, 67258, '<td valign="top">Janine?  Whoever, a lovely capture, with good environmental context.</td>', 'Janine?  Whoever, a lovely capture, with good environmental context.', '2017-05-26 07:33:16.000000', NULL, 1),
(7515545, 1200211, 67258, '<td valign="top">Simple, and all the more pleasing for it.  The balance seems just a tad off, but I can''t quite place my finger on why I feel that.</td>', 'Simple, and all the more pleasing for it.  The balance seems just a tad off, but I can''t quite place my finger on why I feel that.', '2017-05-26 07:34:04.000000', NULL, 1),
(7515546, 1200257, 67258, '<td valign="top">A new woodpecker to me.  The chick poking its head out of the hole is perfect!</td>', 'A new woodpecker to me.  The chick poking its head out of the hole is perfect!', '2017-05-26 07:34:54.000000', NULL, 1),
(7515547, 1200404, 67258, '<td valign="top">Nice clean and simple image.   Could have done with a greater dof so that the back of the beetle was in focus.</td>', 'Nice clean and simple image.   Could have done with a greater dof so that the back of the beetle was in focus.', '2017-05-26 07:35:38.000000', NULL, 1),
(7515548, 1200389, 67258, '<td valign="top">A pleasing image, but I do find myself moving from the eyes out of the frame, especially as I tend to read images from left to right - that means that I have to make the effort to move my eyes over the rest of the image rather than it coming naturally.  Have you tried reversing the photo?</td>', 'A pleasing image, but I do find myself moving from the eyes out of the frame, especially as I tend to read images from left to right - that means that I have to make the effort to move my eyes over the rest of the image rather than it coming naturally.  Have you tried reversing the photo?', '2017-05-26 07:37:37.000000', NULL, 1),
(7515549, 1200362, 67258, '<td valign="top">Lovely.  Godd environmental context - makes for a successful wildlife photo.</td>', 'Lovely.  Godd environmental context - makes for a successful wildlife photo.', '2017-05-26 07:38:09.000000', NULL, 1),
(7515551, 1200290, 67258, '<td valign="top">Absolutely gorgeous - such a quiet and peaceful photo.  It must have been amazing laid in the grass so close.</td>', 'Absolutely gorgeous - such a quiet and peaceful photo.  It must have been amazing laid in the grass so close.', '2017-05-26 07:40:29.000000', NULL, 1),
(7515552, 1200391, 67258, '<td valign="top">Another cracking wildlife photo  Super composition.</td>', 'Another cracking wildlife photo  Super composition.', '2017-05-26 07:41:27.000000', NULL, 1),
(7515553, 1200402, 30364, '<td valign="top">Nice sharp, unequivocal picture is enough to elbow aside my irrational aversion to insect and flower pictures.  I don''t think of it as a wildlife picture, but of course it is; it''s me who has the problem, not you!  Anyway, I don''t believe ''DNMC'' is a valid comment from anyone but the author of the photograph :)  So, nice picture. Thank you.</td>', 'Nice sharp, unequivocal picture is enough to elbow aside my irrational aversion to insect and flower pictures.  I don''t think of it as a wildlife picture, but of course it is; it''s me who has the problem, not you!  Anyway, I don''t believe ''DNMC'' is a valid comment from anyone but the author of the photograph :)  So, nice picture. Thank you.', '2017-05-26 07:45:45.000000', NULL, 1),
(7515554, 1199938, 30364, '<td valign="top">Nice sharp, unequivocal picture is enough to elbow aside my irrational aversion to insect and flower pictures.  I don''t think of it as a wildlife picture, but of course it is; it''s me who has the problem, not you!  Anyway, I don''t believe ''DNMC'' is a valid comment from anyone but the author of the photograph :)  So, nice picture. Thank you.</td>', 'Nice sharp, unequivocal picture is enough to elbow aside my irrational aversion to insect and flower pictures.  I don''t think of it as a wildlife picture, but of course it is; it''s me who has the problem, not you!  Anyway, I don''t believe ''DNMC'' is a valid comment from anyone but the author of the photograph :)  So, nice picture. Thank you.', '2017-05-26 07:46:18.000000', NULL, 1),
(7515555, 1200357, 30364, '<td valign="top">Nice sharp, unequivocal picture is enough to elbow aside my irrational aversion to insect and flower pictures.  I don''t think of it as a wildlife picture, but of course it is; it''s me who has the problem, not you!  Anyway, I don''t believe ''DNMC'' is a valid comment from anyone but the author of the photograph :)  So, nice picture. Thank you.</td>', 'Nice sharp, unequivocal picture is enough to elbow aside my irrational aversion to insect and flower pictures.  I don''t think of it as a wildlife picture, but of course it is; it''s me who has the problem, not you!  Anyway, I don''t believe ''DNMC'' is a valid comment from anyone but the author of the photograph :)  So, nice picture. Thank you.', '2017-05-26 07:46:27.000000', NULL, 1),
(7515556, 1200291, 30364, '<td valign="top">It''s a nice picture of Phil''s cousin, but only moderately interesting to me because it doesn''t communicate anything beyond the fact that you can take a technically-plausible picture.  But I''m probably missing the point.  And he/she certainly is a likeable critter.  Thank you.</td>', 'It''s a nice picture of Phil''s cousin, but only moderately interesting to me because it doesn''t communicate anything beyond the fact that you can take a technically-plausible picture.  But I''m probably missing the point.  And he/she certainly is a likeable critter.  Thank you.', '2017-05-26 07:50:39.000000', NULL, 1),
(7515558, 1200208, 30364, '<td valign="top">Interesting herons but the picture''s a bit messy because for me it seems uncertain and (pardon the pun) unfocused.  There''s so much detail included that the execution has to be perfect it carry it off and alas, it isn''t.  Maybe it''s a severe crop from a long-lens picture, and suffers a bit technically as a result?  It''s a worthy subject but seems too confused to be a strong image.  But nevertheless, thank you.</td>', 'Interesting herons but the picture''s a bit messy because for me it seems uncertain and (pardon the pun) unfocused.  There''s so much detail included that the execution has to be perfect it carry it off and alas, it isn''t.  Maybe it''s a severe crop from a long-lens picture, and suffers a bit technically as a result?  It''s a worthy subject but seems too confused to be a strong image.  But nevertheless, thank you.', '2017-05-26 07:57:12.000000', NULL, 1),
(7515560, 1199920, 30364, '<td valign="top">Well done for trying something different.  It''s a bilious-looking picture, but better that than another colourful duck.  Thank you.</td>', 'Well done for trying something different.  It''s a bilious-looking picture, but better that than another colourful duck.  Thank you.', '2017-05-26 08:09:44.000000', NULL, 1),
(7515561, 1200275, 30364, '<td valign="top">I usually like weird crops, and subjects bisected by the frame, but not this time alas.  The top right corner is a discordant note that makes it impossible for me to see anything else.  Shut one eye; didn''t help much.  But I still like the marsupials which remind me of home.  Thank you</td>', 'I usually like weird crops, and subjects bisected by the frame, but not this time alas.  The top right corner is a discordant note that makes it impossible for me to see anything else.  Shut one eye; didn''t help much.  But I still like the marsupials which remind me of home.  Thank you', '2017-05-26 08:16:04.000000', NULL, 1),
(7515565, 1200213, 30364, '<td valign="top">Nice animals, high cuteness factor, but the picture''s not particularly distinguished by much beyond that.  I''m being a bit unfair though; this is their real, natural environment and how else are you supposed to depict them?  I guess what I''m saying is there''s nothing arresting about the photo, and I think there always should be something transformative or singular added by the photographer, otherwise why take the photograph? But you''re sure right about the cute part!  Thank you.</td>', 'Nice animals, high cuteness factor, but the picture''s not particularly distinguished by much beyond that.  I''m being a bit unfair though; this is their real, natural environment and how else are you supposed to depict them?  I guess what I''m saying is there''s nothing arresting about the photo, and I think there always should be something transformative or singular added by the photographer, otherwise why take the photograph? But you''re sure right about the cute part!  Thank you.', '2017-05-26 09:10:01.000000', NULL, 1),
(7515567, 1200396, 30364, '<td valign="top">Remarkable depth of field effect; so remarkable that it nearly has the opposite of its intended effect of focusing the attention on the critter.  The actual picture of the squirrel (maybe it''s a chipmunk?) is very clean and appealing though.  Thank you.</td>', 'Remarkable depth of field effect; so remarkable that it nearly has the opposite of its intended effect of focusing the attention on the critter.  The actual picture of the squirrel (maybe it''s a chipmunk?) is very clean and appealing though.  Thank you.', '2017-05-26 09:13:59.000000', NULL, 1),
(7515569, 1200062, 30364, '<td valign="top">It''s a very competent picture without any heart in it.  I am unfamiliar with chipmunks and I''d like to have learned something, or felt something, about this chipmunk from looking at the picture.  But I don''t feel any more informed than I did before I looked at it.  I think the photographer''s job is to reveal something that''s otherwise not necessarily evident.  Even if what''s revealed isn''t objective but rather is subjective and particular to your own point of view (actually, especially then).   Not everyone agrees with me, of course.  And it is a very clean, unequivocal picture of the subject.  Thank you.</td>', 'It''s a very competent picture without any heart in it.  I am unfamiliar with chipmunks and I''d like to have learned something, or felt something, about this chipmunk from looking at the picture.  But I don''t feel any more informed than I did before I looked at it.  I think the photographer''s job is to reveal something that''s otherwise not necessarily evident.  Even if what''s revealed isn''t objective but rather is subjective and particular to your own point of view (actually, especially then).   Not everyone agrees with me, of course.  And it is a very clean, unequivocal picture of the subject.  Thank you.', '2017-05-26 09:21:55.000000', NULL, 1),
(7515570, 1200280, 30364, '<td valign="top">Slightly weird perspective, but it presents a surprising &amp; unfamiliar look at whatever bird this may be, and that''s a bonus.  Thank you.</td>', 'Slightly weird perspective, but it presents a surprising & unfamiliar look at whatever bird this may be, and that''s a bonus.  Thank you.', '2017-05-26 09:23:57.000000', NULL, 1),
(7515571, 1200113, 59029, '<td valign="top">looks too good be true...museum diorama?</td>', 'looks too good be true...museum diorama?', '2017-05-26 09:24:50.000000', NULL, 1),
(7515572, 1200377, 59029, '<td valign="top">holy legs Batman! Those are some tall waders.</td>', 'holy legs Batman! Those are some tall waders.', '2017-05-26 09:25:18.000000', NULL, 1),
(7515573, 1200201, 30364, '<td valign="top">There''s nothing you can do with a picture of a duck to make me excited.  I''ve seen too many pictures of ducks, I suppose.  That''s perhaps the point about duck pictures.  The quality of the photography''s very nice though.  Thank you.</td>', 'There''s nothing you can do with a picture of a duck to make me excited.  I''ve seen too many pictures of ducks, I suppose.  That''s perhaps the point about duck pictures.  The quality of the photography''s very nice though.  Thank you.', '2017-05-26 09:26:19.000000', NULL, 1),
(7515574, 1200294, 59029, '<td valign="top">aww no!!! poor turtle.  hope croc/gator broke a few teeth on its shell.</td>', 'aww no!!! poor turtle.  hope croc/gator broke a few teeth on its shell.', '2017-05-26 09:28:20.000000', NULL, 1),
(7515575, 1200069, 59029, '<td valign="top">sharpie?</td>', 'sharpie?', '2017-05-26 09:31:05.000000', NULL, 1),
(7515578, 1200307, 30364, '<td valign="top">Nicely minimalist, which I like, but the rendering of the birds is either too bad, or too good, to be arresting.  By that I mean the birds have to be either perfectly clear and sharp (they aren''t), or so negligently rendered as to be transformative (and again, they aren''t).  What it feels like is near miss.  But it''s a pleasing picture, if not quite as good as it very nearly was!  Thank you.</td>', 'Nicely minimalist, which I like, but the rendering of the birds is either too bad, or too good, to be arresting.  By that I mean the birds have to be either perfectly clear and sharp (they aren''t), or so negligently rendered as to be transformative (and again, they aren''t).  What it feels like is near miss.  But it''s a pleasing picture, if not quite as good as it very nearly was!  Thank you.', '2017-05-26 09:34:00.000000', NULL, 1),
(7515580, 1200356, 59029, '<td valign="top">top 3</td>', 'top 3', '2017-05-26 09:35:54.000000', NULL, 1),
(7515581, 1200169, 67258, '<td valign="top">You can see here how well camouflaged they are against the tree bark.  A pleasing photo.<br/> <br/>The American grey squirrel was introduced to Britain just over a 100 years ago, and the pox that they carry has decimated our native red squirrel population, which are now really quite rare and an endangered species in England.</td>', 'You can see here how well camouflaged they are against the tree bark.  A pleasing photo. The American grey squirrel was introduced to Britain just over a 100 years ago, and the pox that they carry has decimated our native red squirrel population, which are now really quite rare and an endangered species in England.', '2017-05-26 09:44:36.000000', NULL, 1),
(7515582, 1200104, 67258, '<td valign="top">A pleasing close-up portrait of this owl - I''ll take your word for it that it isn''t captive - perhaps a wider shot showing more of the context would help give it more of a wildlife feel.  It must have been incredibly exciting to have a visitor like this - and in daylight. Tawny owls roost in the tree outside my bedroom, but whilst I hear them regularly, I have only seen one once, just as it began to get the first hint of light. Very envious!</td>', 'A pleasing close-up portrait of this owl - I''ll take your word for it that it isn''t captive - perhaps a wider shot showing more of the context would help give it more of a wildlife feel.  It must have been incredibly exciting to have a visitor like this - and in daylight. Tawny owls roost in the tree outside my bedroom, but whilst I hear them regularly, I have only seen one once, just as it began to get the first hint of light. Very envious!', '2017-05-26 09:49:08.000000', NULL, 1),
(7515583, 1200308, 67258, '<td valign="top">The bread doesn''t really add to the shot, and the cut-off gull at the bottom damages the balance.  A hard photo to do well.</td>', 'The bread doesn''t really add to the shot, and the cut-off gull at the bottom damages the balance.  A hard photo to do well.', '2017-05-26 09:50:03.000000', NULL, 1),
(7515584, 1200167, 67258, '<td valign="top">What a wonderful bird - such a vibrant and electric blue.  The fledgling poking its head out of the nest box is great.</td>', 'What a wonderful bird - such a vibrant and electric blue.  The fledgling poking its head out of the nest box is great.', '2017-05-26 09:51:09.000000', NULL, 1),
(7515585, 1200280, 67258, '<td valign="top">Looks as though you have cropped in heavily, a bit too far.  An interesting looking bird - what is it?</td>', 'Looks as though you have cropped in heavily, a bit too far.  An interesting looking bird - what is it?', '2017-05-26 09:51:59.000000', NULL, 1),
(7515586, 1200215, 67258, '<td valign="top">Woah, that is one sinister looking beast!  I am going to have to take your word for it that this is in the wild - Indonesia? Excellent choice of perspective.</td>', 'Woah, that is one sinister looking beast!  I am going to have to take your word for it that this is in the wild - Indonesia? Excellent choice of perspective.', '2017-05-26 09:53:40.000000', NULL, 1),
(7515587, 1200356, 67258, '<td valign="top">Gorgeous!</td>', 'Gorgeous!', '2017-05-26 09:53:54.000000', NULL, 1),
(7515588, 1200062, 67258, '<td valign="top">Cute.  I wish the tip of the tail was in the frame, and the blade of grass in the foreground had been removed prior to pressing the shutter.</td>', 'Cute.  I wish the tip of the tail was in the frame, and the blade of grass in the foreground had been removed prior to pressing the shutter.', '2017-05-26 09:54:46.000000', NULL, 1),
(7515589, 1200275, 67258, '<td valign="top">What great wildlife to have!  It does look as though you may have just missed focus.</td>', 'What great wildlife to have!  It does look as though you may have just missed focus.', '2017-05-26 09:56:12.000000', NULL, 1),
(7515591, 1200377, 67258, '<td valign="top">Very pleasing.  Glad you included the pools of water, providing both balance and environmental context.  Possibly a tad over-sharpened, there is a little haloing around the birds.</td>', 'Very pleasing.  Glad you included the pools of water, providing both balance and environmental context.  Possibly a tad over-sharpened, there is a little haloing around the birds.', '2017-05-26 09:57:34.000000', NULL, 1),
(7515594, 1199938, 47974, '<td valign="top">I am sorry, but for me the definition of wildlife doesn''t include insects.</td>', 'I am sorry, but for me the definition of wildlife doesn''t include insects.', '2017-05-26 10:41:43.000000', NULL, 1),
(7515595, 1199920, 47974, '<td valign="top">I am sorry, but for me the definition of wildlife doesn''t include insects.</td>', 'I am sorry, but for me the definition of wildlife doesn''t include insects.', '2017-05-26 10:41:52.000000', NULL, 1),
(7515596, 1200369, 47974, '<td valign="top">I am sorry, but for me the definition of wildlife doesn''t include insects.</td>', 'I am sorry, but for me the definition of wildlife doesn''t include insects.', '2017-05-26 10:41:55.000000', NULL, 1),
(7515597, 1200357, 47974, '<td valign="top">I am sorry, but for me the definition of wildlife doesn''t include insects.</td>', 'I am sorry, but for me the definition of wildlife doesn''t include insects.', '2017-05-26 10:41:59.000000', NULL, 1),
(7515598, 1200305, 47974, '<td valign="top">I am sorry, but for me the definition of wildlife doesn''t include bugs or snails or slugs.</td>', 'I am sorry, but for me the definition of wildlife doesn''t include bugs or snails or slugs.', '2017-05-26 10:42:18.000000', NULL, 1),
(7515599, 1200404, 47974, '<td valign="top">I am sorry, but for me the definition of wildlife doesn''t include insects.</td>', 'I am sorry, but for me the definition of wildlife doesn''t include insects.', '2017-05-26 10:42:22.000000', NULL, 1),
(7515600, 1200402, 47974, '<td valign="top">I am sorry, but for me the definition of wildlife doesn''t include insects.</td>', 'I am sorry, but for me the definition of wildlife doesn''t include insects.', '2017-05-26 10:42:39.000000', NULL, 1),
(7515601, 1200219, 185712, '<td valign="top">Perfect moment!</td>', 'Perfect moment!', '2017-05-26 10:43:17.000000', NULL, 1),
(7515619, 1200338, 30364, '<td valign="top">I tried to decide if I liked this or not.  Liked won in the end.  It''s a weird wildlife picture but that''s a positive as far as I''m concerned.  It''s quite an interesting photograph, without regard to the challenge topic, and the rascally duck or goose is just a lovely whacky inclusion that prevents it from being a static yawn-inducing landscape.  So what all that amounts to is that I like all the things the picture <i>isn''t.</i>  Very much.  Thank you.</td>', 'I tried to decide if I liked this or not.  Liked won in the end.  It''s a weird wildlife picture but that''s a positive as far as I''m concerned.  It''s quite an interesting photograph, without regard to the challenge topic, and the rascally duck or goose is just a lovely whacky inclusion that prevents it from being a static yawn-inducing landscape.  So what all that amounts to is that I like all the things the picture isn''t.  Very much.  Thank you.', '2017-05-26 12:12:31.000000', NULL, 1),
(7515620, 1200105, 30364, '<td valign="top">Spectacular duck, but the photograph is perhaps sleeping along with him.  I don''t mean that to be as insulting as it may sound; I mean that (for me ... and for everyone who''s even slightly curious, I suppose) a worthy portrait should reveal something unexpected or intimate about the subject.  I think that''s why you rarely see a portrait of a human subject depicted sleeping; it''s excessively passive and uninformative.  But the technical quality of the photography is excellent.  Thank you.</td>', 'Spectacular duck, but the photograph is perhaps sleeping along with him.  I don''t mean that to be as insulting as it may sound; I mean that (for me ... and for everyone who''s even slightly curious, I suppose) a worthy portrait should reveal something unexpected or intimate about the subject.  I think that''s why you rarely see a portrait of a human subject depicted sleeping; it''s excessively passive and uninformative.  But the technical quality of the photography is excellent.  Thank you.', '2017-05-26 12:12:34.000000', NULL, 1),
(7515623, 1200308, 30364, '<td valign="top">Such a strange and negligent photograph.  That''s two of my favourite things right there.  It''s also boldly incomplete, which is my other favourite thing about art.  I can''t say that I love it unconditionally, but I can say that it entertained and challenged me far more than most of the others.  It''d have been a pretty awful picture, had it not had all those aforementioned splendid qualities.  Thank you.</td>', 'Such a strange and negligent photograph.  That''s two of my favourite things right there.  It''s also boldly incomplete, which is my other favourite thing about art.  I can''t say that I love it unconditionally, but I can say that it entertained and challenged me far more than most of the others.  It''d have been a pretty awful picture, had it not had all those aforementioned splendid qualities.  Thank you.', '2017-05-26 12:33:15.000000', NULL, 1),
(7515624, 1200404, 30364, '<td valign="top">I can''t get over my indifference to bug pictures, but the focus in this one is just off enough to make it more interesting than most in the genre.  Plus it''s a very nice, appealing bug.  Thank you.</td>', 'I can''t get over my indifference to bug pictures, but the focus in this one is just off enough to make it more interesting than most in the genre.  Plus it''s a very nice, appealing bug.  Thank you.', '2017-05-26 12:35:25.000000', NULL, 1),
(7515625, 1200052, 30364, '<td valign="top">The critter blends in nicely with the bark of the tree, which is the point of him, I guess.  He rewards a longer look, because he (slowly) becomes more and more resolved as you stare at him.  He even moved a bit, after a minute or so.  Not a ''stunning'' wildlife picture, but we''ve seen plenty of those before.  This is a bit different, although that''s faint praise and both of us know it.  Thank you.</td>', 'The critter blends in nicely with the bark of the tree, which is the point of him, I guess.  He rewards a longer look, because he (slowly) becomes more and more resolved as you stare at him.  He even moved a bit, after a minute or so.  Not a ''stunning'' wildlife picture, but we''ve seen plenty of those before.  This is a bit different, although that''s faint praise and both of us know it.  Thank you.', '2017-05-26 12:41:32.000000', NULL, 1),
(7515626, 1200104, 30364, '<td valign="top">Beautiful owl.  And though it doesn''t at first seem so ''authentic'' for the owl to be perched on whatever unnatural object that is, it actually is a perfectly real setting, well consistent with the true ways of owls.  Nice picture.  Thank you.</td>', 'Beautiful owl.  And though it doesn''t at first seem so ''authentic'' for the owl to be perched on whatever unnatural object that is, it actually is a perfectly real setting, well consistent with the true ways of owls.  Nice picture.  Thank you.', '2017-05-26 12:44:29.000000', NULL, 1),
(7515627, 1200069, 30364, '<td valign="top">Nicely done to capture this raptor right at his own decisive moment.  You really have depicted that moment when the hunter hangs in a balance between stalking and killing.  Thank you.</td>', 'Nicely done to capture this raptor right at his own decisive moment.  You really have depicted that moment when the hunter hangs in a balance between stalking and killing.  Thank you.', '2017-05-26 12:47:48.000000', NULL, 1),
(7515633, 1200275, 163081, '<td valign="top">high iso ruins this image, I think some dfine filter could have made wonders with this otherwise great image. A 6 from me.</td>', 'high iso ruins this image, I think some dfine filter could have made wonders with this otherwise great image. A 6 from me.', '2017-05-26 13:21:05.000000', NULL, 1),
(7515634, 1200169, 163081, '<td valign="top">Nice scene but the sharpening tool was really badly used on one part of the branch. A 6 from me</td>', 'Nice scene but the sharpening tool was really badly used on one part of the branch. A 6 from me', '2017-05-26 13:22:30.000000', NULL, 1),
(7515635, 1200211, 163081, '<td valign="top">Nice catch. centered composition is working here because of the bird''s reflection on the water. A 7 from me</td>', 'Nice catch. centered composition is working here because of the bird''s reflection on the water. A 7 from me', '2017-05-26 13:24:15.000000', NULL, 1),
(7515640, 1200305, 163081, '<td valign="top">Cool picture, 7</td>', 'Cool picture, 7', '2017-05-26 13:25:59.000000', NULL, 1),
(7515641, 1200290, 163081, '<td valign="top">I love rabbits (I have one myself). This is beautiful, nice vivid colors. My top for a ribbon. A 10 from me and my Red Dragon Award <a href="//www.dpchallenge.com/image.php?IMAGE_ID=1173262" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/160000-164999/163081/120/Copyrighted_Image_Reuse_Prohibited_1173262.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/160000-164999/163081/120/Copyrighted_Image_Reuse_Prohibited_1173262.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/160000-164999/163081/120/Copyrighted_Image_Reuse_Prohibited_1173262.jpg"/></a></td>', 'I love rabbits (I have one myself). This is beautiful, nice vivid colors. My top for a ribbon. A 10 from me and my Red Dragon Award ', '2017-05-26 13:28:07.000000', NULL, 1),
(7515642, 1200215, 163081, '<td valign="top">OH MY GOD!!!   This is just amazing. This is the winner. Those eyes staring at the viewer, that tongue coming out,.... scary. A 10 from me and my Blue Dragon Award <a href="//www.dpchallenge.com/image.php?IMAGE_ID=1173261" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/160000-164999/163081/120/Copyrighted_Image_Reuse_Prohibited_1173261.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/160000-164999/163081/120/Copyrighted_Image_Reuse_Prohibited_1173261.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/160000-164999/163081/120/Copyrighted_Image_Reuse_Prohibited_1173261.jpg"/></a></td>', 'OH MY GOD!!!   This is just amazing. This is the winner. Those eyes staring at the viewer, that tongue coming out,.... scary. A 10 from me and my Blue Dragon Award ', '2017-05-26 13:30:30.000000', NULL, 1),
(7515644, 1200308, 163081, '<td valign="top">I don''t know where to look at, there is no real focusing point for my eyes to rest. The 2 ducks on the side is earning you 1 more point. A 6 from me</td>', 'I don''t know where to look at, there is no real focusing point for my eyes to rest. The 2 ducks on the side is earning you 1 more point. A 6 from me', '2017-05-26 13:32:11.000000', NULL, 1),
